<?php require_once __DIR__.'/functions.php';require_once __DIR__.'/app_init.php';require_login();$pdo=dogvive_db();$uid=dogvive_user_id();
if($_SERVER['REQUEST_METHOD']==='POST'){try{$to=(int)($_POST['destinatario']??0);$body=trim((string)($_POST['contenido']??''));if(!$to||$to===$uid||mb_strlen($body)<1||mb_strlen($body)>3000)throw new RuntimeException('Selecciona un destinatario y escribe un mensaje de hasta 3000 caracteres.');$check=$pdo->prepare('SELECT id_usuario,Nombre,Apellido FROM usuario WHERE id_usuario=?');$check->execute([$to]);$recipient=$check->fetch();if(!$recipient)throw new RuntimeException('El destinatario no existe.');$s=$pdo->prepare('INSERT INTO mensaje (Contenido,Fecha,Hora,id_usuario,id_destinatario,Leido) VALUES (?,CURDATE(),CURTIME(),?,?,0)');$s->execute([$body,$uid,$to]);dogvive_notice($pdo,$to,'Mensaje','Tienes un nuevo mensaje de '.($_SESSION['dogvibe_user']['nombre']??'un usuario').'.','mensajes.php');dogvive_flash('success','Mensaje enviado.');header('Location: '.base_url().'/mensajes.php?conversacion='.$to);exit;}catch(Throwable $e){dogvive_flash('error',$e instanceof RuntimeException?$e->getMessage():'No se pudo enviar el mensaje.');header('Location: '.base_url().'/mensajes.php');exit;}}
$users=$pdo->prepare('SELECT id_usuario,Nombre,Apellido,Tipo_usuario FROM usuario WHERE id_usuario<>? ORDER BY Nombre');$users->execute([$uid]);$contacts=$users->fetchAll();$target=(int)($_GET['conversacion']??($contacts[0]['id_usuario']??0));$q=$pdo->prepare('SELECT m.*,u.Nombre,u.Apellido FROM mensaje m JOIN usuario u ON u.id_usuario=m.id_usuario WHERE (m.id_usuario=? AND m.id_destinatario=?) OR (m.id_usuario=? AND m.id_destinatario=?) ORDER BY m.Fecha,m.Hora,m.id_chatprivado');$q->execute([$uid,$target,$target,$uid]);$messages=$q->fetchAll();$success=dogvive_flash('success');$error=dogvive_flash('error');start_app('Mensajes','mensajes');page_wrap_start('Mensajes','Comunícate con propietarios y entrenadores.');if($success)echo '<div class="notice">'.e($success).'</div>';if($error)echo '<div class="error-box">'.e($error).'</div>'; ?>
<div class="message-layout"><aside class="conversation"><h3>Contactos</h3><?php foreach($contacts as $c): ?><a class="<?= $target===(int)$c['id_usuario']?'active':'' ?>" href="<?= e(base_url().'/mensajes.php?conversacion='.(int)$c['id_usuario']) ?>"><span class="avatar avatar-small"><?= e(mb_strtoupper(mb_substr((string)$c['Nombre'],0,1))) ?></span><span><strong><?= e(trim($c['Nombre'].' '.$c['Apellido'])) ?></strong><small class="muted"><?= e((string)$c['Tipo_usuario']) ?></small></span></a><?php endforeach; ?></aside><div class="chat"><div class="chat-header"><strong><?php $ct=array_values(array_filter($contacts,fn($c)=>(int)$c['id_usuario']===$target));echo $ct?e(trim($ct[0]['Nombre'].' '.$ct[0]['Apellido'])):'Selecciona un contacto'; ?></strong></div><div class="chat-body" style="min-height:280px"><?php if(!$messages): ?><p class="muted">No hay mensajes todavía. Envía el primero.</p><?php endif;foreach($messages as $m): ?><div class="bubble <?= (int)$m['id_usuario']===$uid?'user':'' ?>"><?= nl2br(e((string)$m['Contenido'])) ?><small style="display:block"><?= e((string)$m['Fecha']) ?> <?= e(substr((string)$m['Hora'],0,5)) ?> · <?= e(trim($m['Nombre'].' '.$m['Apellido'])) ?></small></div><?php endforeach; ?></div><?php if($target): ?><form class="chat-input" method="post"><input type="hidden" name="destinatario" value="<?= $target ?>"><input name="contenido" maxlength="3000" placeholder="Escribe un mensaje..." required><button class="btn btn-primary" type="submit">Enviar →</button></form><?php endif; ?></div></div><?php page_wrap_end();end_app();
